script:
frappe.ui.form.on('Delivery Note', {
    refresh: function(frm) {


        if(frm.doc.customer) {
            frappe.db.get_value("Customer", frm.doc.customer, "custom_customer_alert").then(r => {

                if (r.message.custom_customer_alert) {
                    frm.set_intro(`<b>Alerte client:</b> <br/> ${r.message.custom_customer_alert}`, 'yellow');
                }
            })
        }

        if(!frm.doc.custom_sms_sent) {
            frm.add_custom_button(__('SMS 💬'), function(){
                frappe.call({
                    method: "sms_delivery_note",
                    args: {
                        doc_name: frm.doc.name
                    }
                }).then(() => frm.reload_doc());
            });
        }

        if(!frm.doc.custom_signed) {
            frm.add_custom_button(__('Signer ✍️'), function(){
            frappe.prompt({
                label: 'Signature',
                fieldname: 'signature',
                fieldtype: 'Signature',
            }, (values) => {
                frm.set_value({
                    custom_signed: 1,
                    custom_signature_client: values.signature,
                    custom_livré: 1,
                    delivery_date: frappe.datetime.get_today()
                }).then(() => {
                if(frm.doc.docstatus === 1) {
                    frm.save('Update');
                } else {
                    frm.save()
                }
                })

            })

            });
        }

        if(!frm.doc.custom_livré && frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Livrer'), function(){
            frm.set_value('custom_livré', 1)
            frm.set_value('delivery_date', frappe.datetime.get_today())
            frm.save('Update');
            });

        }
        if(!frm.doc.custom_imprimé) {
            frm.add_custom_button(__('Imprimer'), function(){
                frm.set_value('custom_imprimé', 1)
                frm.save('Update').then(() => cur_frm.print_doc());

            });
        }

        if(frm.doc.project) {
            frm.add_custom_button(__('📁'), function(){
                const dialog = new frappe.ui.Dialog({
                    size: "extra-large",
            		title: __("Details du projet"),
            		fields: [
            			{
            				fieldname: "content",
            				fieldtype: "HTML",
            			},
            		],
            		primary_action: function () {
            			frappe.set_route('Form', "Project", frm.doc.project);
            		},
            		primary_action_label: __("Projet"),
            	});

            	frappe.call({
                    method: "vt_internal.vt_internal.api.project_details.project_details",
                    args: {project: frm.doc.project}
                }).then((r) => dialog.fields_dict.content.$wrapper.html(r.message.html))
                dialog.show()
            });
            frm.add_custom_button(__('Incident qualité'), function(){
                frappe.new_doc("Quality Incident", {project: frm.doc.project})
            }, __("Create"));
        }



  },
  custom_signature_client: (frm) => {
      frm.set_value("custom_signed", 1)
      frm.set_value("custom_livré", 1)
  },
  custom_livré: (frm) => {
      frm.set_value("delivery_date", frappe.datetime.get_today())
  }
});

const standard_indicator = frappe.listview_settings['Delivery Note'].get_indicator


Object.assign(frappe.listview_settings['Delivery Note'], {
    add_fields: ['project', 'contact_mobile', 'company', 'custom_livré', 'customer_name', 'per_billed', 'custom_sms_sent', 'reference_piece', 'custom_signed'],
/*    hide_name_column: true, // hide the last column which shows the `name`
    hide_name_filter: true,*/

    formatters: {
        custom_imprimé(val, t, doc) {
            return val && doc.custom_signed && "🖨 ✍️" || val && "🖨" || doc.custom_signed && "✍️" || ""
        },
    },

    button: {
	    show: (doc) => {
	      return (doc.custom_sms_sent === 0 || doc.custom_signed === 0) && !doc.custom_livré && doc.docstatus != 2
	    },
		get_description: (doc) => {
			return doc.custom_sms_sent === 0 ? "SMS" : "✍️"
		},
		get_label: (doc) => {
			return doc.custom_sms_sent === 0 ? "SMS" : "✍️"
		},
		action: (doc) => {
		    if(!doc.custom_sms_sent) {
		        frappe.call({
                    method: "sms_delivery_note",
                    args: {
                        doc_name: doc.name
                    }
                }).then(() => cur_list.refresh())
		    } else {
		        frappe.prompt({
                label: 'Signature',
                fieldname: 'signature',
                fieldtype: 'Signature',
            }, (values) => {
                frappe.db.set_value("Delivery Note", doc.name, {
                    custom_signature_client: values.signature,
                    custom_signed: 1,
                    custom_livré: 1,
                    delivery_date: frappe.datetime.get_today()
                }).then(() => {
                    cur_list.refresh()
                    frappe.show_alert({message: 'Signature ajoutée', indicator: 'green'}, 5)
                })
            })
		    }

		}
	},

	get_indicator(doc) {
	    if(doc.status === "Closed") {
	        return standard_indicator(doc)
	    }
        if(!doc.custom_livré) {
            return [__("À livrer"), "purple", "custom_livré,=,0|status,!=,Closed|docstatus,=,1"]
        }

        if(doc.custom_livré && doc.customer_name?.includes("*") && doc.per_billed < 90 && doc.status != "Closed") {
            return [__("EC À facturer"), "green", "customer_name,like,*|custom_livré,=,1|per_billed,<,90|docstatus,=,1|status,!=,Closed"]
        }

        if(doc.per_billed < 90) {
            return [__("À Facturer"), "orange", "status,!=,Closed|docstatus,=,1|custom_livré,=,1|per_billed,<,90|customer_name,not like,*"]
        }

        return standard_indicator(doc)
    },

})

frappe.listview_settings['Quotation Approval'] = {
